contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 skipAmount) public payable {
        require(skipAmount >= 0);
        (uint256 baseBefore, uint256 quoteBefore) = c.getVaultReserve(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.sync(); if (__ESBMC_reverted()) return;
        reverted = false;
        (uint256 baseAfter, uint256 quoteAfter) = c.getVaultReserve(); if (__ESBMC_reverted()) return;
        assert(!reverted && baseAfter == baseBefore && quoteAfter == quoteBefore);
    }
    receive() external payable {}
}

