// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GSPFunding} from "../src/GSPFunding.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GSPFunding c;

    function setUp() public {
        c = new GSPFunding();
    }

    function _run(uint256 skipAmount) internal {
        vm.assume(skipAmount >= 0);
        uint256 baseBefore;
        uint256 quoteBefore;
        try c.getVaultReserve() returns (uint256 __r0, uint256 __r1) { baseBefore = __r0; quoteBefore = __r1; } catch { return; }
        bool reverted;
        try c.sync() {} catch { return; }
        reverted = false;
        uint256 baseAfter;
        uint256 quoteAfter;
        try c.getVaultReserve() returns (uint256 __r0, uint256 __r1) { baseAfter = __r0; quoteAfter = __r1; } catch { return; }
        assertTrue(!reverted && baseAfter == baseBefore && quoteAfter == quoteBefore);
    }

    function testFuzz_run(uint256 skipAmount) public {
        _run(skipAmount);
    }

    receive() external payable {}
}
